begin;
create table public.service_offerings (
 id text primary key, title text not null, category_slug text not null references public.service_categories(slug),
 category_name text not null, icon text not null, vertical text not null,
 base_paisa integer not null check(base_paisa >= 0), visit_paisa integer not null check(visit_paisa >= 0),
 duration_minutes integer not null check(duration_minutes > 0), description text not null,
 included text[] not null, excluded text[] not null, keywords text[] not null, image text not null,
 regions text[] not null, active boolean not null default true, sort_order integer not null default 0
);
alter table public.service_offerings enable row level security;
revoke all on public.service_offerings from public, anon, authenticated;
grant select on public.service_offerings to anon, authenticated;
grant all on public.service_offerings to service_role;
create policy service_offerings_public_read on public.service_offerings for select to anon, authenticated using(active);
insert into public.service_categories(name,slug,description,icon_name)
values ('Plumbing','plumbing','A fresh fitting, installed with care.','wrench'),
('Electrical','electrical','A considered setup for backup power.','zap'),
('Carpentry','carpentry','Give well-loved furniture a little attention.','hammer'),
('Home Cleaning','home-cleaning','A cleaner home. A clearer head.','sparkles'),
('Water Tank Cleaning','water-tank-cleaning','Care for the water your home depends on.','droplets'),
('Sofa & Carpet','sofa-carpet-cleaning','Freshen up your favourite corner.','sofa'),
('Doctor at Home','doctor-at-home','A non-emergency consultation, at home.','stethoscope'),
('Home Nursing','home-nursing','Thoughtful assistance for everyday care.','heart'),
('Physiotherapy','physiotherapy','Support for movement, one session at a time.','activity'),
('Home Salon & Spa','home-salon','A little time, just for you.','scissors'),
('Astrology','astrology','A private, scheduled conversation about your questions and traditions.','sparkles'),
('Home Tutoring','home-tutoring','One focused learning session at home, matched to a subject and grade.','book-open'),
('Home Decorators','home-decorators','A practical in-home consultation for a room refresh or small gathering.','sparkles')
on conflict(slug) do update set name=excluded.name,description=excluded.description,icon_name=excluded.icon_name;
insert into public.service_offerings
